def rect_outline(r0,c0,r1,c1):
    S=set()
    for c in range(c0,c1+1): S.add((r0,c)); S.add((r1,c))
    for r in range(r0,r1+1): S.add((r,c0)); S.add((r,c1))
    return S
def plus(c,arm=12):
    r,b=c; return {(r,b+d) for d in range(-arm,arm+1)} | {(r+d,b) for d in range(-arm,arm+1)}
best=(-1,None,None)
sols=[]
rects={}
for dh in range(1,64):
    for dc in range(1,64):
        if dh+dc==36: rects[(dh,dc)]=None
print('rect shapes', list(rects))
for r0 in range(64):
    for c0 in range(64):
        for (dh,dc) in rects:
            r1=r0+dh; c1=c0+dc
            if r1>63 or c1>63: continue
            S=rect_outline(r0,c0,r1,c1)
            cv=frozenset(p for p in DOTS if p in S)
            if len(cv)<2: continue
            # plus positions
            for a in range(64):
                for b in range(64):
                    P=plus((a,b))
                    cv2=cv | frozenset(p for p in DOTS if p in P)
                    if len(cv2)==8: sols.append((r0,c0,r1,c1,(a,b)))
            if sols: break
    if sols: break
print('solutions found', len(sols), sols[:3])
"}

